def q(v):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        return repr(v)
    if isinstance(v, list):
        return "array[" + ",".join(q(x) for x in v) + "]::text[]" if v else "'{}'::text[]"
    return "'" + str(v).replace("'", "''") + "'"


rows = []
for (slug, name, wiki, city, cc, lat, lng, url, tix, timed, slot, start, dur, tags, lx, ly, note, aliases) in A:
    rows.append("(" + ",".join([q(slug), q(name), q(wiki), q(city), q(cc), q(lat), q(lng), q(url), q(tix), q(timed), q(slot), q(start), q(dur), q(tags), q(lx), q(ly), q(note), q(aliases)]) + ")")

